-- Bloco 2: reescreve somente dicas e passos das questões MC 34 a 66.
-- Enunciados, alternativas, gabaritos, tags e explicações permanecem intactos.
begin;

create temporary table c1_block_02_steps (
  question_id uuid primary key, hints text[] not null, titles text[] not null, steps text[] not null
) on commit drop;


-- Remove os registros legados antes de inserir as versões específicas deste bloco.
delete from public.question_hints where question_id in (select question_id from c1_block_02_steps);
delete from public.question_solution_steps where question_id in (select question_id from c1_block_02_steps);

select format('00000083-0000-4000-8000-%s',lpad((row_number() over(order by question_id)*10+ord)::text,12,'0'))::uuid,
question_id,hint,ord
from c1_block_02_steps cross join lateral unnest(hints) with ordinality as h(hint,ord);

select format('00000093-0000-4000-8000-%s',lpad((row_number() over(order by question_id)*10+ord)::text,12,'0'))::uuid,
question_id,title,step,ord
from c1_block_02_steps
cross join lateral unnest(titles) with ordinality as t(title,ord)
cross join lateral unnest(steps) with ordinality as s(step,step_ord)
where ord=step_ord;

commit;
